import{Q as e,Tt as t,et as n,j as r,nt as i,xt as a}from"./chunks/framework.D7GyxgT6.js";var o=JSON.parse(`{"title":"watermark-js-plus 是什么？","description":"了解如何使用 watermark-js-plus 的框架无关 TypeScript API，为浏览器页面添加可见水印、图片水印和暗水印。","frontmatter":{"layout":"doc","description":"了解如何使用 watermark-js-plus 的框架无关 TypeScript API，为浏览器页面添加可见水印、图片水印和暗水印。"},"headers":[],"relativePath":"zh/guide/what-is-this.md","filePath":"zh/guide/what-is-this.md"}`),s={name:`zh/guide/what-is-this.md`};function c(r,o,s,c,l,u){let d=t(`el-backtop`);return a(),e(`div`,null,[i(d),o[0]||=n(`<h1 id="watermark-js-plus-是什么" tabindex="-1">watermark-js-plus 是什么？ <a class="header-anchor" href="#watermark-js-plus-是什么" aria-label="Permalink to “watermark-js-plus 是什么？”">​</a></h1><p><code>watermark-js-plus</code> 是一个轻量、基于 Canvas 的 TypeScript 浏览器水印库。它可以直接用于原生 JavaScript 和各种前端框架，无需安装框架专用适配器。</p><p>你可以用它为整个页面或指定容器添加可见水印、将水印直接绘制到现有图片中，或者生成和显现低透明度暗水印。</p><h2 id="功能" tabindex="-1">功能 <a class="header-anchor" href="#功能" aria-label="Permalink to “功能”">​</a></h2><ul><li>提供页面、容器、图片和暗水印 API</li><li>支持文本、多行文本、图片和富文本内容</li><li>支持灵活布局、样式、动画和运行时更新</li><li>可选的 DOM 篡改检测与水印恢复</li><li>内置完整的公共 TypeScript 类型声明</li></ul><h2 id="浏览器兼容性" tabindex="-1">浏览器兼容性 <a class="header-anchor" href="#浏览器兼容性" aria-label="Permalink to “浏览器兼容性”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;"><img src="https://raw.githubusercontent.com/alrra/browser-logos/main/src/chrome/chrome_48x48.png" alt="Chrome"></th><th style="text-align:center;"><img src="https://raw.githubusercontent.com/alrra/browser-logos/main/src/firefox/firefox_48x48.png" alt="Firefox"></th><th style="text-align:center;"><img src="https://raw.githubusercontent.com/alrra/browser-logos/main/src/safari/safari_48x48.png" alt="Safari"></th><th style="text-align:center;"><img src="https://raw.githubusercontent.com/alrra/browser-logos/main/src/opera/opera_48x48.png" alt="Opera"></th><th style="text-align:center;"><img src="https://raw.githubusercontent.com/alrra/browser-logos/main/src/edge/edge_48x48.png" alt="Edge"></th><th style="text-align:center;"><img src="https://raw.githubusercontent.com/alrra/browser-logos/master/src/archive/internet-explorer_9-11/internet-explorer_9-11_48x48.png" alt="IE"></th></tr></thead><tbody><tr><td style="text-align:center;">Latest ✔</td><td style="text-align:center;">Latest ✔</td><td style="text-align:center;">Latest ✔</td><td style="text-align:center;">Latest ✔</td><td style="text-align:center;">Latest ✔</td><td style="text-align:center;">11 ✔</td></tr></tbody></table><h2 id="internet-explorer" tabindex="-1"><a href="./extra/ie.html">Internet Explorer 🚀</a> <a class="header-anchor" href="#internet-explorer" aria-label="Permalink to “Internet Explorer”">​</a></h2><p>支持IE11，部分支持IE10和IE9。</p>`,9)])}var l=r(s,[[`render`,c]]);export{o as __pageData,l as default};